using System;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class RestoreStandaloneSkill03{
 public static object Run(){if(Application.isPlaying)throw new Exception("Stop play first");const string path="Assets/3DBattle/NewPlayer/Attack/Previews/NewKnight_Skill_03_Preview.anim";var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);var backup=AssetDatabase.LoadAssetAtPath<AnimationClip>(path.Replace(".anim","_BeforeForwardFacing.anim"));if(clip==null||backup==null)throw new Exception("Missing clip or backup");var combo=GameObject.Find("New Knight Combo Sequence Preview").GetComponentInChildren<Animator>().runtimeAnimatorController.animationClips[0];string before=EditorJsonUtility.ToJson(combo);Undo.RecordObject(clip,"Restore standalone skill3");string name=clip.name;EditorUtility.CopySerialized(backup,clip);clip.name=name;EditorUtility.SetDirty(clip);var a=GameObject.Find("Attack 05 - Skill_03").GetComponentInChildren<Animator>();clip.SampleAnimation(a.gameObject,0);AssetDatabase.SaveAssets();var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return new{restored=path,frames=Mathf.RoundToInt(clip.length*clip.frameRate),comboUnchanged=before==EditorJsonUtility.ToJson(combo)};}
}
